#[test]
fn every_benchmark_task_maps_to_the_expected_production_harness() {
    let expected = [
        CampaignHarnessRoute::NativeReadQuestion,
        CampaignHarnessRoute::AgentHost,
        CampaignHarnessRoute::AgentHost,
        CampaignHarnessRoute::AgentHost,
        CampaignHarnessRoute::AgentHost,
        CampaignHarnessRoute::RuntimeDebugging,
        CampaignHarnessRoute::RuntimeDebuggingVisual,
    ];
    for (task, expected) in BENCHMARK_TASKS.iter().zip(expected) {
        assert_eq!(
            CampaignHarnessRoute::for_task(task.id).expect("harness route"),
            expected
        );
    }
    assert!(CampaignHarnessRoute::for_task(BENCHMARK_TASKS[5].id)
        .expect("runtime route")
        .requires_runtime_debugging());
    assert!(CampaignHarnessRoute::for_task(BENCHMARK_TASKS[6].id)
        .expect("visual route")
        .requires_runtime_debugging());
}

#[test]
fn fixture_reset_isolates_candidate_project_from_host_evaluator() {
    let root = tempfile::tempdir().expect("fixture root");
    let store = CampaignFixtureStore::open(root.path().to_path_buf()).expect("fixture store");
    let campaign = BenchmarkCampaign::new("campaign-a", plan()).expect("campaign");
    let schedule = campaign.runs[0].schedule.clone();
    let fixture = campaign.plan.tasks[schedule.task_index].fixture.clone();
    let first = store
        .reset_for_run(&campaign.campaign_id, &schedule, &fixture)
        .expect("first fixture");
    let contamination = first.candidate_project.join("contamination.txt");
    fs::write(&contamination, b"must disappear").expect("contamination");
    assert!(!first.hidden_oracle().starts_with(&first.candidate_project));
    assert!(!first.host_evaluator_root().starts_with(&first.candidate_project));
    assert!(first.visible_contract.starts_with(&first.candidate_project));

    let second = store
        .reset_for_run(&campaign.campaign_id, &schedule, &fixture)
        .expect("second fixture");
    assert!(!second.candidate_project.join("contamination.txt").exists());
    let visible = fs::read_to_string(second.visible_contract).expect("visible contract");
    let hidden = fs::read_to_string(second.hidden_oracle()).expect("hidden oracle");
    assert!(!visible.contains("hidden_token"));
    assert!(hidden.contains("hidden_token"));
}

